def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a list to store the maximum volume that can be occupied by a subset of the first i items
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i-1] <= j:
                dp[i][j] = max(dp[i-1][j], dp[i-1][j - volumes[i-1]] + volumes[i-1])
            else:
                dp[i][j] = dp[i-1][j]

    # Find the maximum volume that can be occupied by all items
    max_volume = dp[n][V]

    # Calculate the minimum remaining space
    min_remaining = V - max_volume

    return min_remaining

